        ON DELETE CASCADE
)
TABLESPACE pg_default;

-- Index: IX_DeckAccolades_DeckId

CREATE INDEX "IX_DeckAccolades_DeckId"
    ON public."DeckAccolades" USING btree
    ("DeckId" ASC NULLS LAST)
    TABLESPACE pg_default;

-- Table: public."MasterVaultDecks"
-- The Master Vault response for each imported deck, without its cards

CREATE TABLE public."MasterVaultDecks"
(
    "Uuid" text COLLATE pg_catalog."default" NOT NULL,
    "Data" jsonb NOT NULL,
    "FetchedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_MasterVaultDecks" PRIMARY KEY ("Uuid")
)
TABLESPACE pg_default;

-- Table: public."MasterVaultCards"
-- Cards from Master Vault deck responses, by Master Vault card id. Most are shared between decks

CREATE TABLE public."MasterVaultCards"
(
    "Id" text COLLATE pg_catalog."default" NOT NULL,
    "Card" jsonb NOT NULL,
    CONSTRAINT "PK_MasterVaultCards" PRIMARY KEY ("Id")
)
TABLESPACE pg_default;

-- View: public."DeckStats"

-- Each deck's record over the last 12 months, across every player who used it. Keyed by the deck's
-- Master Vault id stored on GamePlayers, so deleting and re-importing a deck doesn't reset it.
-- A dominant win is a win by keys or concession, after 3+ turns, with the opponent on 0 keys.
-- Sealed games (random decks) and mirror matches (same deck on both sides) don't count.
-- Refreshed periodically by the lobby (REFRESH MATERIALIZED VIEW CONCURRENTLY).
CREATE MATERIALIZED VIEW public."DeckStats" AS
SELECT gp."DeckUuid" AS "Uuid",
       count(*) AS "Games",
       count(*) FILTER (WHERE gp."PlayerId" = g."WinnerId") AS "Wins",
       count(*) FILTER (
           WHERE gp."PlayerId" = g."WinnerId"
             AND g."WinReason" IN ('keys', 'concede')
             AND COALESCE(gp."Turn", 0) >= 3
             AND COALESCE(opp."Keys", 0) = 0
       ) AS "DominantWins"
FROM public."GamePlayers" gp
JOIN public."Games" g ON g."Id" = gp."GameId"
LEFT JOIN public."GamePlayers" opp ON opp."GameId" = gp."GameId" AND opp."PlayerId" <> gp."PlayerId"
WHERE gp."DeckUuid" IS NOT NULL
  AND opp."DeckUuid" IS DISTINCT FROM gp."DeckUuid"
  AND g."WinnerId" IS NOT NULL
  AND g."FinishedAt" IS NOT NULL
  AND g."GameFormat" IS DISTINCT FROM 'sealed'
  AND g."StartedAt" >= now() - interval '12 months'
GROUP BY gp."DeckUuid";

-- Index: IX_DeckStats_Uuid (unique, required for a concurrent refresh)

CREATE UNIQUE INDEX "IX_DeckStats_Uuid"
    ON public."DeckStats" USING btree
    ("Uuid" COLLATE pg_catalog."default" ASC NULLS LAST)
    TABLESPACE pg_default;

-- Table: public."UserMonthlyStats"

-- Each user's stats for a calendar month (UTC), cached once the month has ended since they can't change.
-- "Version" is UserStatsService's SummaryVersion; rows from an older version are recomputed on read.
CREATE TABLE public."UserMonthlyStats"
(
    "UserId" integer NOT NULL,
    "Month" date NOT NULL,
    "Version" integer NOT NULL,
    "Data" jsonb NOT NULL,
    "ComputedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_UserMonthlyStats" PRIMARY KEY ("UserId", "Month"),
    CONSTRAINT "FK_UserMonthlyStats_Users_UserId" FOREIGN KEY ("UserId")
        REFERENCES public."Users" ("Id") MATCH SIMPLE
        ON UPDATE NO ACTION
        ON DELETE CASCADE
)

TABLESPACE pg_default;

-- Table: public."UserWrapped"

-- Each player's annual Wrapped snapshot, saved by server/scripts/wrapped.js (see WrappedService).
-- "EmailedAt" is set when the Wrapped email is sent, and kept when the snapshot is generated again.
CREATE TABLE public."UserWrapped"
(
    "UserId" integer NOT NULL,
    "Year" integer NOT NULL,
    "Version" integer NOT NULL,
    "Data" jsonb NOT NULL,
    "GeneratedAt" timestamp without time zone NOT NULL,
    "EmailedAt" timestamp without time zone,
    CONSTRAINT "PK_UserWrapped" PRIMARY KEY ("UserId", "Year"),
    CONSTRAINT "FK_UserWrapped_Users_UserId" FOREIGN KEY ("UserId")
        REFERENCES public."Users" ("Id") MATCH SIMPLE
        ON UPDATE NO ACTION
        ON DELETE CASCADE
)

TABLESPACE pg_default;

